<?php require_once dirname(__DIR__).'/includes/auth.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT * FROM quizzes WHERE id=?');$s->execute([$id]);$quiz=$s->fetch()?:exit('Quiz não encontrado.');$s=db()->prepare('SELECT a.*,u.name,u.email,ROUND(IF(a.max_score>0,a.score/a.max_score*100,0)) percent FROM attempts a JOIN users u ON u.id=a.user_id WHERE a.quiz_id=? AND a.submitted_at IS NOT NULL ORDER BY a.submitted_at DESC');$s->execute([$id]);$attempts=$s->fetchAll();$avg=count($attempts)?round(array_sum(array_column($attempts,'percent'))/count($attempts)):0;$pageTitle='Resultados · '.$quiz['title'];require dirname(__DIR__).'/includes/header.php'; ?>
<section class="admin-head compact"><div><a class="back" href="<?= e(url('admin/')) ?>">← Voltar</a><div class="eyebrow">RESULTADOS</div><h1><?= e($quiz['title']) ?></h1></div><a class="button secondary" href="<?= e(url('admin/export.php?id='.$id)) ?>">↓ Exportar CSV</a></section><div class="stats"><article><span>✓</span><div><strong><?= count($attempts) ?></strong><small>participações</small></div></article><article><span>◉</span><div><strong><?= $avg ?>%</strong><small>média geral</small></div></article></div>
<section class="table-card"><div class="table-wrap"><table><thead><tr><th>Colaborador</th><th>E-mail</th><th>Pontuação</th><th>Aproveitamento</th><th>Concluído</th><th></th></tr></thead><tbody><?php foreach($attempts as $a): ?><tr><td><strong><?= e($a['name']) ?></strong></td><td><?= e($a['email']) ?></td><td><?= e($a['score']) ?> / <?= e($a['max_score']) ?></td><td><div class="mini-progress"><i style="width:<?= (int)$a['percent'] ?>%"></i></div><strong><?= (int)$a['percent'] ?>%</strong></td><td><?= date('d/m/Y H:i',strtotime($a['submitted_at'])) ?></td><td><a href="<?= e(url('admin/attempt.php?id='.$a['id'])) ?>">Ver respostas →</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>

